def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    - Collapse multiple '/' characters.
    - Resolve '.' (current directory) and '..' (parent directory) components.
    - The result is an absolute path that does not end with a trailing slash
      unless it is the root '/'.
    """
    if not path:
        return '/'
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root, ignore extra '..'
        else:
            stack.append(p)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

