def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount.
    coins: list of positive integers (coin denominations), unlimited supply.
    amount: non‑negative integer.
    Returns -1 if the amount cannot be formed.
    """
    # Edge case
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] = min coins for amount i
    # Use a value larger than any possible answer (amount+1 is safe)
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

